//! #249 — Gitee rejects the `x-access-token` Basic-auth username that GitHub
//! and Gitea accept ("remote: The token username invalid", HTTP 403), so every
//! Gitee remote failed regardless of how valid the token was. This drives the
//! real `github_push_inner` against a real Gitee repository to prove the
//! credential callback now authenticates there.
//!
//! `#[ignore]`d — needs network + a Gitee account. Run with:
//!   SOLOMD_GITEE_URL=https://gitee.com/<user>/<repo>.git \
//!   SOLOMD_GITEE_TOKEN=<token> \
//!   cargo test --test gitee_auth_e2e_test -- --ignored --nocapture

use std::fs;
use std::process::Command;

fn env(name: &str) -> Option<String> {
    std::env::var(name).ok().filter(|v| !v.is_empty())
}

#[test]
#[ignore]
fn push_to_gitee_authenticates() {
    let (url, token) = match (env("SOLOMD_GITEE_URL"), env("SOLOMD_GITEE_TOKEN")) {
        (Some(u), Some(t)) => (u, t),
        _ => {
            eprintln!("skipped: set SOLOMD_GITEE_URL and SOLOMD_GITEE_TOKEN");
            return;
        }
    };

    let ws = std::env::temp_dir().join(format!("solomd-gitee-e2e-{}", std::process::id()));
    let _ = fs::remove_dir_all(&ws);
    fs::create_dir_all(&ws).unwrap();
    fs::write(ws.join("note.md"), "# from the gitee auth e2e test\n").unwrap();

    let git = |args: &[&str]| {
        let out = Command::new("git").args(args).current_dir(&ws).output().unwrap();
        assert!(out.status.success(), "git {:?} failed: {}", args, String::from_utf8_lossy(&out.stderr));
    };
    git(&["init", "-q"]);
    git(&["config", "user.email", "e2e@example.com"]);
    git(&["config", "user.name", "e2e"]);
    git(&["add", "-A"]);
    git(&["commit", "-qm", "e2e"]);
    // The setup fetch below runs through the SYSTEM git, whose credential
    // helper must not be involved (it may have a stale username cached).
    // Embed the account + token in a throwaway URL for setup only; `origin`
    // is then pointed at the bare URL so the assertion exercises OUR
    // credential callback, not git's helper.
    let owner = url.split('/').nth(3).unwrap_or_default().to_string();
    let auth_url = url.replacen("https://", &format!("https://{}:{}@", owner, token), 1);
    git(&["remote", "add", "origin", &auth_url]);
    // Match whatever the remote already uses so the push is a fast-forward-able
    // ref rather than a new branch on an unrelated history.
    git(&["fetch", "-q", "origin"]);
    git(&["branch", "-M", "master"]);
    git(&["reset", "--soft", "origin/master"]);
    git(&["add", "-A"]);
    git(&["commit", "-qm", "e2e push probe"]);
    git(&["remote", "set-url", "origin", &url]);

    let res = app_lib::github_sync::github_push_inner(
        ws.to_string_lossy().to_string(),
        token,
        Some("e2e: gitee auth probe".to_string()),
    );

    let _ = fs::remove_dir_all(&ws);
    assert!(
        res.is_ok(),
        "push to Gitee must authenticate — got: {:?}",
        res.err()
    );
}

//! Behavioral integration test for v4.0 multi-workspace federation.
//!
//! Spawns the actual `solomd-mcp` binary as a subprocess, drives it over
//! stdio with raw JSON-RPC frames (mirroring the README's "Verifying"
//! recipe), and asserts:
//!
//!   * a `list_notes` call with no `workspace` arg returns the default
//!     workspace's notes (back-compat for single-`--workspace` clients);
//!   * a `list_notes` call with `workspace: "wsB"` (alias) returns wsB's;
//!   * a `list_notes` call with the absolute path of wsB returns wsB's;
//!   * a `list_notes` call with a bogus workspace returns an error frame
//!     listing the registered aliases.
//!
//! Why subprocess-driven: the rmcp `serve(stdio())` machinery and the
//! `#[tool_router]` macro-generated request-routing code only get exercised
//! when the binary actually starts. The unit tests in `tools.rs` cover the
//! pure `resolve_workspace` logic; this test covers the protocol surface.

use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

fn fresh_workspace(label: &str, note_name: &str, body: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let dir = std::env::temp_dir().join(format!("solomd-mcp-multi-{label}-{nanos}"));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join(note_name), body).unwrap();
    dir.canonicalize().unwrap()
}

fn binary_path() -> PathBuf {
    // CARGO_BIN_EXE_<name> is set by cargo for integration tests targeting
    // the named bin in this crate.
    PathBuf::from(env!("CARGO_BIN_EXE_solomd-mcp"))
}

/// Drive the server through `initialize` → `notifications/initialized` →
/// each `request`, return the matching response per id (responses for
/// notifications never come back). Frames are line-delimited JSON.
fn drive(args: &[&str], requests: &[serde_json::Value]) -> Vec<serde_json::Value> {
    let mut child = Command::new(binary_path())
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn solomd-mcp");

    let mut stdin = child.stdin.take().unwrap();
    // Initialize handshake.
    let init = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 0,
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": {"name": "p4-federation-test", "version": "0"}
        }
    });
    writeln!(stdin, "{}", init).unwrap();
    let initialized = serde_json::json!({
        "jsonrpc": "2.0",
        "method": "notifications/initialized"
    });
    writeln!(stdin, "{}", initialized).unwrap();

    // Collect ids we expect responses for.
    let mut want_ids: Vec<i64> = vec![0];
    for req in requests {
        writeln!(stdin, "{}", req).unwrap();
        if let Some(id) = req.get("id").and_then(|v| v.as_i64()) {
            want_ids.push(id);
        }
    }
    drop(stdin); // close stdin → server exits cleanly when done.

    let stdout = child.stdout.take().unwrap();
    let mut responses_by_id: std::collections::HashMap<i64, serde_json::Value> =
        std::collections::HashMap::new();
    for line in BufReader::new(stdout).lines().map_while(Result::ok) {
        let v: serde_json::Value = match serde_json::from_str(&line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if let Some(id) = v.get("id").and_then(|i| i.as_i64()) {
            responses_by_id.insert(id, v);
        }
    }
    let _ = child.wait();

    // Return responses in the order the caller's requests were submitted
    // (skip the initialize response — caller doesn't ask for it explicitly).
    requests
        .iter()
        .filter_map(|req| req.get("id").and_then(|v| v.as_i64()))
        .map(|id| {
            responses_by_id
                .remove(&id)
                .unwrap_or_else(|| panic!("no response for id {id}"))
        })
        .collect()
}

#[test]
fn back_compat_single_workspace_no_arg() {
    // Exactly the v3.x invocation: one --workspace, no client-side workspace
    // arg. Must keep working unchanged.
    let ws = fresh_workspace("solo", "only.md", "# Solo\n");
    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": { "name": "list_notes", "arguments": {} }
    });
    let resps = drive(&["--workspace", &ws.to_string_lossy()], &[req]);
    let r = &resps[0];
    let text = extract_text_payload(r);
    assert!(
        text.contains("only.md"),
        "expected only.md in response, got: {text}"
    );
}

#[test]
fn multi_workspace_default_to_first() {
    let ws_a = fresh_workspace("mwA", "alpha.md", "# A\n");
    let ws_b = fresh_workspace("mwB", "beta.md", "# B\n");
    let arg_a = format!("wsA={}", ws_a.display());
    let arg_b = format!("wsB={}", ws_b.display());

    // No `workspace` arg → default = first = wsA.
    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 11,
        "method": "tools/call",
        "params": { "name": "list_notes", "arguments": {} }
    });
    let resps = drive(
        &["--workspace", &arg_a, "--workspace", &arg_b],
        &[req.clone()],
    );
    let text = extract_text_payload(&resps[0]);
    eprintln!("default frame: {text}");
    assert!(
        text.contains("alpha.md"),
        "default workspace should serve wsA notes; got: {text}"
    );
    assert!(
        !text.contains("beta.md"),
        "default workspace must not leak wsB notes; got: {text}"
    );
}

#[test]
fn multi_workspace_explicit_alias_targets_other() {
    let ws_a = fresh_workspace("mwA2", "alpha.md", "# A\n");
    let ws_b = fresh_workspace("mwB2", "beta.md", "# B\n");
    let arg_a = format!("wsA={}", ws_a.display());
    let arg_b = format!("wsB={}", ws_b.display());

    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 21,
        "method": "tools/call",
        "params": {
            "name": "list_notes",
            "arguments": { "workspace": "wsB" }
        }
    });
    let resps = drive(
        &["--workspace", &arg_a, "--workspace", &arg_b],
        &[req],
    );
    let text = extract_text_payload(&resps[0]);
    eprintln!("alias frame: {text}");
    assert!(text.contains("beta.md"), "got: {text}");
    assert!(!text.contains("alpha.md"), "got: {text}");
}

#[test]
fn multi_workspace_absolute_path_targets_other() {
    let ws_a = fresh_workspace("mwA3", "alpha.md", "# A\n");
    let ws_b = fresh_workspace("mwB3", "beta.md", "# B\n");
    let arg_a = format!("wsA={}", ws_a.display());
    let arg_b = format!("wsB={}", ws_b.display());

    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 31,
        "method": "tools/call",
        "params": {
            "name": "list_notes",
            "arguments": { "workspace": ws_b.to_string_lossy() }
        }
    });
    let resps = drive(
        &["--workspace", &arg_a, "--workspace", &arg_b],
        &[req],
    );
    let text = extract_text_payload(&resps[0]);
    eprintln!("abspath frame: {text}");
    assert!(text.contains("beta.md"), "got: {text}");
}

#[test]
fn multi_workspace_unknown_alias_errors() {
    let ws_a = fresh_workspace("mwA4", "alpha.md", "# A\n");
    let ws_b = fresh_workspace("mwB4", "beta.md", "# B\n");
    let arg_a = format!("wsA={}", ws_a.display());
    let arg_b = format!("wsB={}", ws_b.display());

    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 41,
        "method": "tools/call",
        "params": {
            "name": "list_notes",
            "arguments": { "workspace": "nope" }
        }
    });
    let resps = drive(
        &["--workspace", &arg_a, "--workspace", &arg_b],
        &[req],
    );
    let resp = &resps[0];
    eprintln!("unknown frame: {resp}");
    // Two valid encodings depending on whether the macro maps it to a
    // protocol-level error or a tool-level error frame: check both.
    let serialized = serde_json::to_string(resp).unwrap();
    assert!(
        serialized.contains("unknown workspace"),
        "expected unknown-workspace error, got: {serialized}"
    );
    assert!(
        serialized.contains("wsA") && serialized.contains("wsB"),
        "error should enumerate available aliases, got: {serialized}"
    );
}

/// Pull the human-readable text payload out of a `tools/call` response,
/// regardless of whether rmcp returned the JSON content as a `text` block
/// or a `json` block. Falls back to the whole serialized response if the
/// shape is unfamiliar so test failures still print something useful.
fn extract_text_payload(resp: &serde_json::Value) -> String {
    if let Some(content) = resp.pointer("/result/content").and_then(|c| c.as_array()) {
        let mut out = String::new();
        for item in content {
            if let Some(t) = item.get("text").and_then(|v| v.as_str()) {
                out.push_str(t);
                out.push('\n');
            } else if item.get("type").and_then(|v| v.as_str()) == Some("json") {
                out.push_str(&serde_json::to_string(item).unwrap_or_default());
                out.push('\n');
            } else {
                // Some encodings put the JSON under a `data` field.
                out.push_str(&serde_json::to_string(item).unwrap_or_default());
                out.push('\n');
            }
        }
        if !out.is_empty() {
            return out;
        }
    }
    serde_json::to_string(resp).unwrap_or_default()
}

//! v4.1 regression test for the `export_note` MCP tool — closes the
//! v4.0.2-surfaced gap where docx export was untestable from CI.
//!
//! Specifically: a Markdown blockquote MUST appear as text in the
//! exported .docx's `word/document.xml`. Pre-v4.0.2 the in-app docx
//! pipeline silently dropped blockquote content (rendered as empty
//! bordered paragraphs). This test would have caught it at PR time.
//!
//! Spawns the actual `solomd-mcp` binary, drives `export_note` over
//! stdio JSON-RPC, then unzips the resulting .docx + greps document.xml.
//!
//! Skipped automatically when `node` isn't on PATH or when
//! `app/scripts/solomd-export.mjs` can't be located.

use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

fn binary_path() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_solomd-mcp"))
}

/// Locate `app/scripts/solomd-export.mjs` from the test process's cwd
/// (which cargo sets to the crate dir, i.e. `mcp-server/`). Walk up to
/// the repo root.
fn find_export_script() -> Option<PathBuf> {
    let crate_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let candidates = [
        crate_dir.join("../app/scripts/solomd-export.mjs"),
        crate_dir.join("../../app/scripts/solomd-export.mjs"),
    ];
    for c in &candidates {
        if c.is_file() {
            return c.canonicalize().ok();
        }
    }
    None
}

fn have_node() -> bool {
    Command::new("node")
        .arg("--version")
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn fresh_dir(label: &str) -> PathBuf {
    let nanos = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let dir = std::env::temp_dir().join(format!("solomd-mcp-export-{label}-{nanos}"));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

/// Drive an `initialize` → `export_note` round-trip and return the
/// matching response frame.
fn drive_export(workspace: &Path, args_json: serde_json::Value, script_path: &Path) -> serde_json::Value {
    let mut child = Command::new(binary_path())
        .arg("--workspace").arg(workspace)
        .env("SOLOMD_EXPORT_SCRIPT", script_path)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn solomd-mcp");
    let mut stdin = child.stdin.take().unwrap();
    writeln!(stdin, r#"{{"jsonrpc":"2.0","id":0,"method":"initialize","params":{{"protocolVersion":"2025-11-25","capabilities":{{}},"clientInfo":{{"name":"export-test","version":"0"}}}}}}"#).unwrap();
    writeln!(stdin, r#"{{"jsonrpc":"2.0","method":"notifications/initialized"}}"#).unwrap();
    let req = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": { "name": "export_note", "arguments": args_json }
    });
    writeln!(stdin, "{}", req).unwrap();
    drop(stdin);
    let stdout = child.stdout.take().unwrap();
    let mut found = serde_json::Value::Null;
    for line in BufReader::new(stdout).lines().map_while(Result::ok) {
        let v: serde_json::Value = match serde_json::from_str(&line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if v.get("id").and_then(|i| i.as_i64()) == Some(1) {
            found = v;
            break;
        }
    }
    let _ = child.wait();
    found
}

/// Read `word/document.xml` from a docx (zip) on disk.
fn extract_document_xml(docx_path: &Path) -> String {
    let f = std::fs::File::open(docx_path).expect("open docx");
    let mut zip = zip::ZipArchive::new(f).expect("zip parse");
    let mut entry = zip.by_name("word/document.xml").expect("document.xml in docx");
    let mut s = String::new();
    entry.read_to_string(&mut s).expect("read document.xml");
    s
}

/// Pre-v4.0.2 regression: blockquote content was silently dropped
/// from docx export (the in-app code emitted empty bordered paragraphs
/// because it tried to read `Paragraph.options.children` which the
/// `docx` library doesn't expose publicly). This test asserts the
/// fix stays fixed.
#[test]
fn export_note_docx_preserves_blockquote_text() {
    let Some(script) = find_export_script() else {
        eprintln!("skipping: app/scripts/solomd-export.mjs not found");
        return;
    };
    if !have_node() {
        eprintln!("skipping: node not on PATH");
        return;
    }
    let ws = fresh_dir("blockquote");
    let out_dir = fresh_dir("blockquote-out");
    std::fs::write(
        ws.join("note.md"),
        "# Document\n\nNormal paragraph.\n\n> first quoted line\n> second quoted line\n\nAfter the quote.\n",
    ).unwrap();
    let out = out_dir.join("note.docx");

    let resp = drive_export(
        &ws,
        serde_json::json!({
            "path": "note.md",
            "format": "docx",
            "output_path": out.to_string_lossy(),
        }),
        &script,
    );

    assert!(resp.get("error").is_none(), "export_note returned an error: {resp}");
    assert!(out.exists(), "docx output not written: {}", out.display());

    let xml = extract_document_xml(&out);
    assert!(xml.contains("first quoted line"), "blockquote line 1 missing from document.xml; got len={}", xml.len());
    assert!(xml.contains("second quoted line"), "blockquote line 2 missing from document.xml");
    assert!(xml.contains("Normal paragraph"), "non-quoted text also missing — likely a broader regression");
    assert!(xml.contains("After the quote"), "post-blockquote paragraph missing");
}

/// Sanity: the simpler html path should also include the blockquote text
/// (markdown-it's html: true config means our tweak from #54 is also
/// covered here).
#[test]
fn export_note_html_preserves_blockquote_text() {
    let Some(script) = find_export_script() else {
        return;
    };
    if !have_node() {
        return;
    }
    let ws = fresh_dir("html");
    let out_dir = fresh_dir("html-out");
    std::fs::write(ws.join("note.md"), "# T\n\n> hello quoted\n").unwrap();
    let out = out_dir.join("note.html");

    let resp = drive_export(
        &ws,
        serde_json::json!({
            "path": "note.md",
            "format": "html",
            "output_path": out.to_string_lossy(),
        }),
        &script,
    );

    assert!(resp.get("error").is_none(), "export_note returned an error: {resp}");
    let html = std::fs::read_to_string(&out).expect("read html");
    assert!(html.contains("hello quoted"), "blockquote text missing from html");
    assert!(html.contains("<blockquote"), "no <blockquote> element in html");
}

/// Safety guard: writing INSIDE the workspace requires --allow-write.
#[test]
fn export_note_rejects_workspace_internal_write_without_flag() {
    let Some(script) = find_export_script() else {
        return;
    };
    if !have_node() {
        return;
    }
    let ws = fresh_dir("guard");
    std::fs::write(ws.join("note.md"), "# T\n").unwrap();

    let resp = drive_export(
        &ws,
        serde_json::json!({
            "path": "note.md",
            "format": "docx",
            "output_path": ws.join("inside.docx").to_string_lossy(),
        }),
        &script,
    );
    let err = resp.get("error").unwrap_or(&serde_json::Value::Null);
    let msg = err.get("message").and_then(|m| m.as_str()).unwrap_or("");
    assert!(msg.contains("allow-write"), "expected allow-write guard, got: {err}");
}

//! v4.0 Pillar 3 — end-to-end self-test for the trace pipeline.
//!
//! Goes through the full producer → on-disk → reader path the way the
//! Panel will use it at runtime:
//!   1. `Emitter::open` against a fresh `<workspace>/.solomd/agent-runs/<run_id>/`
//!   2. Emit a realistic chat run (run_started, prompt, tool call+result,
//!      model_done, run_ended).
//!   3. `read_trace` round-trips every line.
//!   4. `replay_prefix` returns the right slice.
//!
//! This stays in `tests/` (an integration test target) so it exercises
//! the public `app_lib` API exactly as the Tauri commands do.

use app_lib::trace::{self, Emitter, RunKind};
use std::fs;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

fn fresh_run_dir(label: &str) -> (PathBuf, String) {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let workspace =
        std::env::temp_dir().join(format!("solomd-trace-e2e-{label}-{nanos}"));
    let run_id = format!("20260430-142307-{:06x}", (nanos & 0xFFFFFF) as u32);
    let dir = workspace
        .join(".solomd")
        .join("agent-runs")
        .join(&run_id);
    fs::create_dir_all(&dir).unwrap();
    (dir, run_id)
}

#[test]
fn end_to_end_panel_chat_run() {
    let (dir, run_id) = fresh_run_dir("e2e-chat");

    // Producer side — what P1's panel runner will do post-merge.
    {
        let em = Emitter::open(&dir, run_id.clone()).unwrap();
        em.run_started(RunKind::Panel, "anthropic", "claude-sonnet-4-6", None, None)
            .unwrap();
        em.prompt("user", "Summarize daily/2026-04-29.md").unwrap();
        em.model_call("anthropic", "claude-sonnet-4-6", 1, 4).unwrap();
        em.tool_call(
            "read_note",
            "tc_aaa",
            &serde_json::json!({"path": "daily/2026-04-29.md"}),
        )
        .unwrap();
        em.tool_result("tc_aaa", "# 2026-04-29\n- shipped v4 panel\n", None)
            .unwrap();
        em.model_done("You shipped v4 panel.", 110, 14, "stop").unwrap();
        em.run_ended("ok", 110, 14, 0.00033, None).unwrap();
    }

    // Reader side — what the TraceView and MCP read_agent_trace do.
    let lines = trace::read_trace(&dir).unwrap();
    assert_eq!(lines.len(), 7);
    assert_eq!(lines[0].kind, "run_started");
    assert_eq!(lines[0].run_id, run_id);
    assert_eq!(lines[3].kind, "tool_call");
    assert_eq!(
        lines[3].payload.get("tool_call_id").and_then(|v| v.as_str()),
        Some("tc_aaa"),
    );
    assert_eq!(lines[4].kind, "tool_result");
    assert_eq!(lines[6].kind, "run_ended");

    // Replay-prefix slice for "replay from the model_done turn" (seq 6)
    // should give us run_started + prompt + model_call + tool_call +
    // tool_result (5 lines, seqs 1..=5).
    let prefix = trace::replay_prefix(&dir, 6).unwrap();
    assert_eq!(prefix.len(), 5);
    assert_eq!(prefix.last().unwrap().seq, 5);
    assert_eq!(prefix.last().unwrap().kind, "tool_result");
}

#[test]
fn end_to_end_truncates_giant_tool_result() {
